catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        return;
    }

    var rewardUtilsGa = new GlideAjax('x_1921751_employ_0.RewardUtils');
    rewardUtilsGa.addParam('sysparm_name', 'getRewardTypeDetails');
    rewardUtilsGa.addParam('sysparm_reward_id', newValue);
    rewardUtilsGa.getXMLAnswer(function(answer) {
        if (answer == 'Not Found') g_form.addErrorMessage("Reward type not found");
        var response = JSON.parse(answer);

        if (response.maxValue > 0) {
            g_form.setDisplay('amount', true);
			g_form.setMandatory('amount', true);
			g_form.setMandatory('leave_days', false);
            g_form.setDisplay('leave_days', false);
        } else {
			g_form.setMandatory('amount', false);
            g_form.setDisplay('amount', false);
            g_form.setDisplay('leave_days', true);
			g_form.setMandatory('leave_days', true);
        }
    });

}
